create table if not exists commands(id uuid primary key default gen_random_uuid(),tenant_id uuid references tenants(id) on delete cascade,user_id uuid references users(id),channel_id uuid references channels(id),project_id uuid references projects(id),job_id uuid references automation_jobs(id),command text not null,status text,created_at timestamptz not null default now());
create table if not exists audit_logs(id uuid primary key default gen_random_uuid(),tenant_id uuid references tenants(id) on delete cascade,user_id uuid references users(id),channel_id uuid references channels(id),project_id uuid references projects(id),job_id uuid references automation_jobs(id),command text,old_state jsonb,new_state jsonb,request_id text,worker text,reason text,metadata jsonb not null default '{}',created_at timestamptz not null default now());
